            Pat::LiquidHaskellEnd
            | Pat::PragmaEnd
            | Pat::PragmaAt0End
            | Pat::PragmaAt1End
            | Pat::TypeApplicationAt2End
            | Pat::TypeApplicationAt3End
            | Pat::PragmaAt2End
            | Pat::PragmaAt4End
            | Pat::CommentsAt0End
